// 사운드 효과를 위한 AudioContext 생성
const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();

// 간단한 비프음 생성
function createBeep(frequency: number, duration: number) {
  const oscillator = audioContext.createOscillator();
  const gainNode = audioContext.createGain();

  oscillator.connect(gainNode);
  gainNode.connect(audioContext.destination);

  oscillator.type = 'sine';
  oscillator.frequency.value = frequency;

  gainNode.gain.setValueAtTime(0, audioContext.currentTime);
  gainNode.gain.linearRampToValueAtTime(0.3, audioContext.currentTime + 0.01);
  gainNode.gain.linearRampToValueAtTime(0, audioContext.currentTime + duration);

  oscillator.start(audioContext.currentTime);
  oscillator.stop(audioContext.currentTime + duration);
}

export const sounds = {
  move: () => createBeep(440, 0.1), // A4 note
  rotate: () => createBeep(523.25, 0.1), // C5 note
  drop: () => createBeep(329.63, 0.15), // E4 note
  clear: () => {
    createBeep(659.25, 0.1); // E5 note
    setTimeout(() => createBeep(880, 0.15), 100); // A5 note
  },
  gameOver: () => {
    createBeep(440, 0.1);
    setTimeout(() => createBeep(415.30, 0.1), 100);
    setTimeout(() => createBeep(392, 0.2), 200);
  }
};
